    html.dark .post-content p {
        color: var(--color-muted-dark);
    }

    /*
     * Photos bleed past the text column on the right only (left edge stays
     * flush with the text) — out to flush with <main>'s own outer edge,
     * using its existing md:p-6/lg:p-8 scale rather than a new constant,
     * so the bleed always matches the page's real gutter at every
     * breakpoint. On mobile photos stay inside the text column.
     */
    @media (min-width: 48rem) {
        .bleed {
            width: calc(100% + 1.5rem);
            margin-inline-end: -1.5rem;
        }
    }

    @media (min-width: 64rem) {
        .bleed {
            width: calc(100% + 2rem);
            margin-inline-end: -2rem;
        }
