      // Link text becomes extra classes (e.g. [ultra-wide](url)); bare URL = no extra classes
      const linkText = link.children?.[0]?.value?.trim() || '';
      const extraClass = linkText && linkText !== link.url ? ` ${linkText}` : '';

      // Create lite embed with thumbnail and play button
