import { visit } from 'unist-util-visit';

const VIDEO_EXTENSIONS = /\.(mp4|mov|webm|ogg)(\?.*)?$/i;
const IMAGEKIT_BASE = 'https://ik.imagekit.io/';

const MIME_TYPES = {
  mp4: 'video/mp4',
  mov: 'video/mp4',
  webm: 'video/webm',
  ogg: 'video/ogg',
};

function getPoster(url) {
  if (!url.startsWith(IMAGEKIT_BASE)) return '';
  return `${url.split('?')[0]}/ik-thumbnail.jpg`;
}

function getVideoType(url) {
  const ext = url.match(/\.(\w+)(\?|$)/)?.[1]?.toLowerCase();
  return MIME_TYPES[ext] || 'video/mp4';
}

export function remarkVideoPlayer() {
  return (tree) => {
    visit(tree, 'paragraph', (node, index, parent) => {
      if (node.children.length !== 1) return;
      const child = node.children[0];
      if (child.type !== 'link') return;

      const url = child.url;
      if (!VIDEO_EXTENSIONS.test(url)) return;

      // [wide](url), [wide mb-3](url), etc. — any link text becomes extra classes; bare URL = no extra classes
      const linkText = child.children?.[0]?.value?.trim() || '';
      const sizeClass = linkText && linkText !== url ? ` ${linkText}` : '';

      const poster = getPoster(url);
      const posterAttr = poster ? `poster="${poster}"` : '';

      parent.children[index] = {
        type: 'html',
        value: `<div class="video-player${sizeClass}">
  <video playsinline preload="none" ${posterAttr}>
    <source src="${url}" type="${getVideoType(url)}">
  </video>
  <div class="video-player-overlay">
    <button class="video-player-btn" aria-label="Play video">
      <svg viewBox="0 0 80 80" width="64" height="64">
        <circle cx="40" cy="40" r="40" fill="rgba(0,0,0,0.5)"/>
        <polygon points="32,24 32,56 60,40" fill="white"/>
      </svg>
    </button>
  </div>
</div>`,
      };
    });
  };
}
