import { getCollection, type CollectionEntry } from "astro:content";

export type Project = CollectionEntry<"workbench">;

export function hasPage(project: Project): boolean {
	return Boolean(project.body?.trim());
}

export function projectDetails(project: Project): string {
	const { role, with: partner } = project.data;
	return [role, partner && `with ${partner}`].filter(Boolean).join(" · ");
}

// "Startups, organizations, music videos, a book and a comic." Most common
// types first; plurals just add an "s", which holds for every type so far.
export function summarizeTypes(projects: Project[]): string {
	const counts = new Map<string, number>();
	for (const { data } of projects) {
		counts.set(data.type, (counts.get(data.type) ?? 0) + 1);
	}

	const phrases = [...counts]
		.sort((a, b) => b[1] - a[1])
		.map(([type, count]) =>
			count > 1 ? `${type}s` : `${/^[aeiou]/.test(type) ? "an" : "a"} ${type}`,
		);

	const list =
		phrases.length > 1
			? `${phrases.slice(0, -1).join(", ")} and ${phrases.at(-1)}`
			: (phrases[0] ?? "");
	return `${list.charAt(0).toUpperCase()}${list.slice(1)}.`;
}

export async function getProjects(): Promise<Project[]> {
	const projects = await getCollection("workbench");
	projects.sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());
	return projects;
}
