---
import Carousel from "./Carousel.astro";
import { formatPostDate, type FeedPost } from "../lib/feed";

interface Props {
	post: FeedPost;
	priority?: boolean;
}

// Everything is read on the feed itself: long posts expand in place. Each post
// still has its own page under /feed/, just not linked from here.
const { post, priority } = Astro.props;
const { title, note, date, monthOnly, photos, text, readingMinutes, Content } = post;
const displayDate = formatPostDate(date, monthOnly);

const kind = photos.length > 0 ? "album" : title ? "long" : "short";
const metaClass = "mb-1 text-xs tabular-nums text-muted dark:text-muted-dark";
---

{
	kind === "album" && (
		<article class="py-6">
			<p class={metaClass}>
				{displayDate}
				{note && <span class="note">{note}</span>}
			</p>
			{title && <h2 class="mb-3 text-lg">{title}</h2>}
			<Carousel
				label={title ?? `Post from ${displayDate}`}
				photos={photos}
				priority={priority}
			/>
			{text && (
				<p class="mt-3 text-sm text-muted dark:text-muted-dark">{text}</p>
			)}
		</article>
	)
}
{
	kind === "long" && (
		<article class="group py-6" data-expandable>
			<p class={metaClass}>
				{displayDate} · {readingMinutes} min read
				{note && <span class="note">{note}</span>}
			</p>
			<h2 class="text-lg">
				<button
					type="button"
					class="cursor-pointer text-left"
					aria-expanded="false"
					data-toggle
				>
					<span class="link">{title}</span>
				</button>
			</h2>
			<div class="expandable post-content text-sm">
				<Content />
			</div>
			<button
				type="button"
				class="show-less mt-3 cursor-pointer text-xs text-muted hover:text-evening dark:text-muted-dark dark:hover:text-sunset"
				data-less
			>
				Show less
			</button>
		</article>
	)
}
{
	// Short posts are shown whole, like a tweet.
	kind === "short" && (
		<article class="py-6">
			<p class={metaClass}>
				{displayDate}
				{note && <span class="note">{note}</span>}
			</p>
			<div class="post-content">
				<Content />
			</div>
		</article>
	)
}

<style>
	/* Handwritten aside next to the date, in the same hand as the site name. */
	.note {
		margin-inline-start: 0.5rem;
		font-family: var(--font-handwriting);
		font-size: 1.125rem;
		line-height: 1;
		color: var(--color-evening);
	}

	:global(html.dark) .note {
		color: var(--color-sunset);
	}

	/* Collapsed: four lines, fading out. Clicking anywhere on them expands. */
	.expandable {
		max-height: 5rem;
		overflow: hidden;
		mask-image: linear-gradient(to bottom, black 40%, transparent);
		cursor: pointer;
	}

	.show-less {
		display: none;
	}

	[data-open] .expandable {
		max-height: none;
		mask-image: none;
		cursor: auto;
	}

	[data-open] .show-less {
		display: block;
	}
</style>

<script>
	for (const post of document.querySelectorAll<HTMLElement>("[data-expandable]")) {
		const toggle = post.querySelector<HTMLButtonElement>("[data-toggle]")!;
		const body = post.querySelector<HTMLElement>(".expandable")!;
		const less = post.querySelector<HTMLButtonElement>("[data-less]")!;

		const setOpen = (open: boolean) => {
			post.toggleAttribute("data-open", open);
			toggle.setAttribute("aria-expanded", String(open));
		};

		toggle.addEventListener("click", () => setOpen(!post.hasAttribute("data-open")));
		body.addEventListener("click", () => setOpen(true));
		less.addEventListener("click", () => {
			setOpen(false);
			// Long posts collapse from below; bring the post's top back into view.
			post.scrollIntoView({ block: "nearest" });
		});
	}
</script>

