/*
 * Collapsed: about four lines, fading out. Opening animates the height to
 * auto where the browser supports interpolate-size; elsewhere it just
 * opens instantly. The fade is a mask taller than the text, slid down out
 * of the way when open, so it eases away along with the height.
 */
.expandable {
	interpolate-size: allow-keywords;
	height: 5rem;
	overflow: hidden;
	mask-image: linear-gradient(to bottom, black calc(100% - 3rem), transparent);
	mask-size: 100% calc(100% + 3rem);
	mask-position: top;
	mask-repeat: no-repeat;
	transition:
		height 0.4s ease,
		mask-size 0.4s ease;
}

[data-open] .expandable {
	height: auto;
	mask-size: 100% calc(100% + 6rem);
}

@media (prefers-reduced-motion: reduce) {
	.expandable {
		transition: none;
	}
}

