import { formatType, hasPage, projectImage, type Project } from "../lib/workbench";

interface Props {
	project: Project;
	priority?: boolean;
}

const { project, priority } = Astro.props;
const { title, type, role, description, date, url } = project.data;
const image = projectImage(project);

// Same linking as the list: a write-up gets its own page, otherwise the
// project links out to where it lives, if anywhere.
const href = hasPage(project) ? `/workbench/${project.id}/` : url;
const external = !hasPage(project) && Boolean(url);
const Frame = href ? "a" : "div";
---

<li class="mb-14">
	<Frame
		href={href}
		target={external ? "_blank" : undefined}
		rel={external ? "noopener noreferrer" : undefined}
		data-external-icon={external ? "" : undefined}
		class:list={["frame bleed block", href && "group"]}
	>
		{/* A widescreen frame: the project's still, or a title card without one. */}
		<div class="relative aspect-[2.39/1] overflow-hidden rounded-sm bg-[#0b0b0b]">
			{
				image && (
					<img
						src={image}
						alt=""
						loading={priority ? "eager" : "lazy"}
						decoding="async"
						class="absolute inset-0 h-full w-full object-cover transition-transform duration-700 ease-out group-hover:scale-[1.03]"
					/>
				)
			}
			<div
				class:list={[
					"absolute inset-0 flex flex-col p-5 text-white sm:p-7",
					image
						? "justify-end bg-linear-to-t from-black/75 via-black/20 to-transparent"
						: "items-center justify-center text-center",
				]}
			>
				<p class="credit mb-1.5 text-white/70">
					{formatType(type)} · <span class="tabular-nums">{date.getFullYear()}</span>
				</p>
				<h2
					class:list={[
						"text-2xl leading-tight text-white sm:text-4xl",
						external && "external-icon",
					]}
				>
					{title}
				</h2>
			</div>
		</div>
	</Frame>
	<p class="mt-3 text-sm text-muted dark:text-muted-dark">{description}</p>
	<p class="credit mt-1.5 text-muted dark:text-muted-dark">{role}</p>
</li>

<style>
	/* Small, spaced-out capitals, like the credits on a title card. */
	.credit {
		font-size: 0.6875rem;
		letter-spacing: 0.16em;
		text-transform: uppercase;
	}
</style>

